  outside: "sensor.vehicle_temperature_outside",
  asleep: "binary_sensor.vehicle_asleep",
  teslaCharger: "binary_sensor.vehicle_charger",
  teslaCharging: "binary_sensor.vehicle_charging",
  doors: "lock.vehicle_doors",
  sentry: "switch.vehicle_sentry_mode",
  trunk: "cover.vehicle_trunk",
  location: "device_tracker.vehicle_location_tracker",
  hvac: "climate.vehicle_hvac_climate_system",
  efficiency: "sensor.vehicle_battery_efficiency_score",
  lastUpdate: "sensor.vehicle_data_last_update_time",
  tpmsFl: "sensor.vehicle_tpms_front_left",
  tpmsFr: "sensor.vehicle_tpms_front_right",
  tpmsRl: "sensor.vehicle_tpms_rear_left",
  tpmsRr: "sensor.vehicle_tpms_rear_right",
  daily: "sensor.vehicle_daily",
  trips: "sensor.vehicle_trips",
  lastTrip: "sensor.vehicle_last_trip",
  totalDistance: "sensor.vehicle_total_distance",
  costKm: "sensor.vehicle_cost_per_km",
  performance: "sensor.vehicle_monthly_performance",
  charges: "sensor.vehicle_charges",
  lastCharge: "sensor.vehicle_last_charge",
  missingPrice: "sensor.vehicle_charges_needing_price",
  chargePower: "sensor.ev_charger_power",
  chargerMode: "sensor.ev_charger_mode",
  chargeRate: "sensor.vehicle_charging_rate",
  finish: "sensor.vehicle_charging_finish_time",
  remaining: "sensor.vehicle_charging_time_remaining",
  estimate: "sensor.vehicle_charging_price_estimate",
  target: "input_number.tesla_target_soc",
  ready: "input_datetime.tesla_ready_by_time",
  bestStart: "sensor.tesla_best_charge_start_text_by_deadline",
  bestEnd: "sensor.tesla_best_charge_end_text_by_deadline",
  bestPrice: "sensor.tesla_best_charge_price_by_deadline",
  minutes: "sensor.tesla_charge_minutes_needed",
  missingKwh: "sensor.tesla_missing_wall_kwh",
  montaState: "sensor.ev_charger_state",
  montaCharge: "sensor.ev_charger_last_charge",
  montaCable: "binary_sensor.ev_charger_cable_plugged_in",
  montaMeter: "sensor.ev_charger_last_meter_reading",
