    const stops = [[5, [79, 145, 220]], [15, [92, 190, 215]], [25, [119, 205, 190]], [35, [225, 188, 111]], [50, [238, 124, 79]], [70, [235, 78, 70]]];
    if (value2 <= stops[0][0]) return `rgb(${stops[0][1]})`;
