    const scroller = this.shadowRoot.querySelector(".scroll");
    if (!scroller) return;
    const stop = (event) => event.stopPropagation();
    ["click", "dblclick", "touchstart", "touchmove", "touchend"].forEach(
      (type) => scroller.addEventListener(type, stop, { passive: true })
    );
